function writeStore(data){assertUser();const copy={...data,updatedAt:Date.now()};const text=JSON.stringify(copy);if(text.length>800000)throw Error('مساحة السبورة ممتلئة، صدّر أو أرشف الجلسات القديمة');localStorage.setItem(ownerKey(),text);const cfg=state().settings;if(cfg&&typeof cfg==='object'){cfg.imamSmartBoardData={owner:currentUser(),data:copy};const ok=g.__IMAM_BASE__?.save?.();if(ok===false)throw Error('تعذر حفظ نسخة الأكاديمية');}return copy;}
function newId(){return g.crypto?.randomUUID?.()||`board-${Date.now()}-${Math.random().toString(36).slice(2)}`;}
