function flush(){if(!b.sessionId)return false;try{const base=readStore(),items=Array.isArray(base.sessions)?base.sessions:[];const existing=items.findIndex(x=>x.id===b.sessionId);const record={id:b.sessionId,studentId:b.studentId,chapter:b.chapter,from:b.from,to:b.to,activity:b.activity,drawings:b.drawings,notes:b.notes,privateNote:b.privateNote,publicExplanation:b.publicExplanation,scienceBook:b.scienceBook,lesson:b.lesson,stepIndex:b.stepIndex,activePrepId:b.activePrepId,status:'draft',createdAt:existing>=0?items[existing].createdAt:Date.now(),updatedAt:Date.now()};if(existing>=0)items[existing]=record;else items.push(record);writeStore({...base,sessions:items.slice(-120)});b.dirty=false;b.savedAt=Date.now();status('المسودة محفوظة على هذا الجهاز');return true;}catch(e){status('تعذر الحفظ، لم تُحفظ المسودة');notify('تعذر حفظ السبورة. تحقق من المساحة المتاحة.','error');return false;}}
