async function loadVerses(){const list=typeof S!=='undefined'?S:[];const chapter=Number($('ib-chapter').value),from=Number($('ib-from').value),to=Number($('ib-to').value);if(!list[chapter-1]||!Number.isInteger(from)||!Number.isInteger(to)||from<1||to<from||to>list[chapter-1].a||to-from>100)return notify('اختر نطاق آيات صحيحًا لا يزيد عن 101 آية','error');b.chapter=chapter;b.from=from;b.to=to;b.verse=from;b.teacherWord='';b.verses=[];resetView();renderScience();const requestId=++quranRequest;$('ib-verses').textContent='جارٍ تحميل النص المعتمد…';try{if(typeof g.fetchQpcHafsChapter!=='function')throw Error('مصدر المصحف غير متاح');const arr=await g.fetchQpcHafsChapter(chapter);if(!accountStillValid()||requestId!==quranRequest||b.chapter!==chapter||b.from!==from||b.to!==to)return;b.verses=arr.filter(x=>x.ayah>=from&&x.ayah<=to);if(!b.verses.length)throw Error('نطاق غير محمل');showVerses();dirty();}catch(_){if(accountStillValid()&&requestId===quranRequest&&$('ib-verses'))$('ib-verses').textContent='تعذر تحميل الآيات. حمّل نص المصحف أو اتصل بالإنترنت ثم أعد المحاولة.';}}
function showVerses(){const host=$('ib-verses');if(!host)return;host.style.fontSize=b.fontSize+'px';host.replaceChildren();for(const v of b.verses){const line=document.createElement('div');line.className='ib-ayah';line.dataset.ayah=v.ayah;line.classList.toggle('ib-curtained',b.curtain.includes(v.ayah));const number=document.createElement('button');number.type='button';number.className='ib-ayah-number';number.textContent=`۞ ${v.ayah}`;number.dataset.selectAyah=v.ayah;line.append(number);const words=String(v.text).split(/\s+/).filter(Boolean);for(let i=0;i<words.length;i++){const span=document.createElement('button');span.type='button';span.className='ib-word';span.dataset.ayah=v.ayah;span.dataset.word=i;span.dataset.value=words[i];span.textContent=b.hides.includes(`${v.ayah}:${i}`)?'◻◻◻':words[i];line.append(span);}host.append(line);}drawCanvas();broadcast();}
