function scientificImporter(){if(!accountStillValid())return;const existing=$('ib-science-import');if(existing){existing.remove();return;}const el=$('ib-science-content');if(!el)return;const form=document.createElement('form');form.id='ib-science-import';form.className='ib-science-editor';form.innerHTML='<h4>استيراد كتب المجمع إلى هذا الجهاز</h4><p>حمّل ملفات المطورين من مجمع الملك فهد رسميًا، واستخرج ملف JSON أو CSV. اختر نوعه وراجع محتواه. هذا الاستيراد لا يغيّر القرآن أو سجلات الطلاب.</p><label>نوع الملف<select name="kind"><option value="verse">التفسير الميسر — تفسير الآيات</option><option value="word">الميسر في غريب القرآن — معاني الكلمات</option></select></label><label>ملفات المطورين الرسمية (JSON أو CSV)<input name="file" type="file" accept=".json,.csv" multiple required></label><label class="ib-science-consent"><input name="official" type="checkbox" required> أؤكد أن الملف اختير من حزمة مجمع الملك فهد الرسمية بعد التحقق من المصدر وحق الاستخدام.</label><div class="ib-science-actions"><button type="submit">استيراد وحفظ للمراجعة دون إنترنت</button><button type="button" data-cmd="scienceImport">إلغاء</button></div><small>المصدر: qurancomplex.gov.sa/techquran/dev/ — يُعرض المصدر مع كل بطاقة. لا يعد البرنامج صحة أي ملف غير متحقق منها آليًا.</small>';
 form.addEventListener('submit',async event=>{event.preventDefault();if(!accountStillValid())return;const button=form.querySelector('[type="submit"]');button.disabled=true;try{const kind=form.elements.namedItem('kind').value;const files=form.elements.namedItem('file').files;const ok=form.elements.namedItem('official').checked;const result=await root.BoardTafsir.importFiles(files,kind,ok);notify(`حُفظ ${result.count} مدخلًا علميًا محليًا، برجاء مراجعة نسبة التغطية وصحة الملف`,'success');form.remove();renderScience();}catch(e){notify('تعذر استيراد المصدر: '+(e?.message||'ملف غير صالح'),'error');}finally{button.disabled=false;}});el.append(form);}
async function shareImportedScience(){if(!accountStillValid()||!canShow())return;const adapter=root.BoardTafsir;if(!adapter)return notify('مكتبة التفسير غير متاحة','error');const {chapter,ayah,word}=scienceSelection();let x=null;try{x=(word&&await adapter.getWord(chapter,ayah,word))||await adapter.getVerse(chapter,ayah);}catch(_){return notify('تعذر قراءة مادة التفسير','error');}if(!accountStillValid()||b.chapter!==chapter||b.verse!==ayah||b.teacherWord!==word)return;if(!x)return notify('لا يوجد تفسير متاح لهذا الموضع','info');if(!confirm('هل راجعت هذه المادة العلمية وحقوق استخدامها وتريد عرضها للطالب؟'))return;b.publicExplanation=`${x.kind==='word'?'معنى الكلمة':x.book||'التفسير الميسر'}: ${x.content}\nالمصدر: ${x.book?'مستودع تجميع التفاسير (بيانات غير محققة تلقائيًا)':adapter.SOURCES[x.kind]?.title}`;const box=$('ib-public');if(box)box.value=b.publicExplanation;dirty();broadcast();notify('ظهرت المادة المختارة في شاشة الطالب','success');}

