function scienceEditor(){if(!accountStillValid())return;const old=$('ib-science-editor');if(old){old.remove();return;}const host=$('ib-science-content');if(!host)return;const card=selectedScienceCard(),sel=scienceSelection(),editor=document.createElement('form');editor.id='ib-science-editor';editor.className='ib-science-editor';editor.innerHTML=`<h4>إضافة بطاقة علمية محلية</h4><p>يُرجى نسخ نص تملك حق استعماله، أو صياغة ملخص المحفظ مع توثيق المصدر. لا تعتمد الأكاديمية تفسيرًا آليًا.</p><label>نوع البطاقة<select name="kind">${scienceTypes.map(t=>`<option value="${esc(t)}" ${t===card?.type?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>الكلمة (اتركها فارغة لبطاقة الآية)<input name="word" maxlength="100" value="${esc(card?.word??sel.word)}"></label><label>المحتوى العلمي<textarea name="content" maxlength="1800" required>${esc(card?.content||'')}</textarea></label><label>اسم المصدر/الطبعة<input name="sourceTitle" maxlength="180" value="${esc(card?.sourceTitle||'')}" required></label><label>رابط المصدر (اختياري)<input name="sourceUrl" type="url" maxlength="350" value="${esc(card?.sourceUrl||'')}"></label><label class="ib-science-consent"><input name="rights" type="checkbox" required> أؤكد أن لدي حق إدخال هذه المادة واستخدامها في العرض التعليمي.</label><div class="ib-science-actions"><button type="submit">حفظ البطاقة</button><button type="button" data-cmd="scienceCancel">إلغاء</button></div><small>المراجعة العلمية وترخيص المادة مسؤولية الجهة التي تنشرها.</small>`;
editor.addEventListener('submit',e=>{e.preventDefault();saveScienceCard(editor);});host.append(editor);}
function saveScienceCard(form){if(!accountStillValid())return;const v=new FormData(form),type=String(v.get('kind')||''),word=cleanText(v.get('word'),100).trim(),content=cleanText(v.get('content'),1800).trim(),sourceTitle=cleanText(v.get('sourceTitle'),180).trim(),rawUrl=cleanText(v.get('sourceUrl'),350).trim();if(!scienceTypes.includes(type)||content.length<5||sourceTitle.length<3||v.get('rights')!=='on')return notify('اكتب محتوى ومصدرًا واضحين وأقرّ بحق الاستخدام','error');let sourceUrl='';if(rawUrl){try{const u=new URL(rawUrl);if(!['https:','http:'].includes(u.protocol))throw Error('invalid');sourceUrl=u.href;}catch(_){return notify('رابط المصدر غير صالح','error');}}
const {chapter,ayah}=scienceSelection();if(!validRange(chapter,ayah,ayah))return notify('اختر آية صحيحة','error');try{const store=readStore(),items=Array.isArray(store.scienceCards)?store.scienceCards.filter(x=>x&&(x.chapter!==chapter||x.ayah!==ayah||x.word!==word)):[];items.push({id:newId(),chapter,ayah,word,type,content,sourceTitle,sourceUrl,enteredBy:currentUser(),rightsAsserted:true,reviewStatus:'teacher-entry',updatedAt:Date.now()});writeStore({...store,scienceCards:items.slice(-180)});renderScience();notify('حُفظت البطاقة في حساب المحفظ مع بيانات مصدرها؛ لم تُعتمد علميًا تلقائيًا','success');}catch(e){notify('تعذر حفظ البطاقة العلمية: '+e.message,'error');}}
function shareScienceCard(){const x=selectedScienceCard();if(!x)return notify('لا توجد بطاقة لهذا الموضع','info');if(!x.rightsAsserted)return notify('لا يُسمح بعرض بطاقة لم يُقر بحق استخدامها','error');if(!confirm('إظهار هذه المادة للطالب؟ تحقق من صحتها وحقوقها؛ لم تعتمدها الأكاديمية آليًا.'))return;b.publicExplanation=`${x.type}: ${x.content}\nالمصدر: ${x.sourceTitle}`;const pub=$('ib-public');if(pub)pub.value=b.publicExplanation;dirty();broadcast();notify('ظهر الشرح الذي اخترته فقط في شاشة الطالب','success');}
function scienceQuiz(){const card=selectedScienceCard();if(!card)return notify('أضف أولًا بطاقة علمية لهذا الموضع','info');const label=card.word||`الآية ${card.ayah}`;b.game=card.type==='حكم تجويدي'?`ما الحكم التجويدي في «${label}»؟`:card.type==='معنى كلمة'?`ما معنى «${label}»؟`:`ما المعنى العام للآية ${card.ayah}؟`;dirty();broadcast();notify('عُرض السؤال فقط. تظهر الإجابة إذا اخترت مشاركة البطاقة','info');}
function resetView(){b.hides=[];b.curtain=[];b.focus=false;b.lens=false;b.reveal=0;b.game='';b.effect='';document.querySelectorAll('#ib-effects>*').forEach(x=>x.remove());$('ib-area')?.classList.remove('ib-focus','ib-lens');}

function reading(){if(nativeEditor)closeNativeEditor();resetView();shutdownAudio();if($('ib-verses'))showVerses();broadcast();}
function pauseDisplay(){b.pausedDisplay=!b.pausedDisplay;broadcast();notify(b.pausedDisplay?'تم إخفاء محتوى شاشة الطالب مؤقتًا':'تم استئناف شاشة الطالب','info');}
function studentName(){const s=students().find(x=>String(x.id)===String(b.studentId));return String(s?.name||s?.fullName||'');}
function outgoing(){const safeName=b.studentFirstName?studentName().split(/\s+/)[0]:studentName();return{type:'update',student:safeName,chapter:b.chapter,from:b.from,to:b.to,verse:b.verse,verses:b.verses.map(v=>({ayah:v.ayah,text:String(v.text)})),hides:b.hides.slice(),curtain:b.curtain.slice(),publicExplanation:b.publicExplanation,drawings:b.drawings.slice(),fontSize:b.fontSize,effect:b.effect,publicPrompt:cleanText(b.game,650),activity:b.activity,paused:b.pausedDisplay,ts:Date.now()};}
function broadcast(){if(!accountStillValid()){closeStudentDisplay();return;}if(!channel||!display||display.closed)return;if(b.pausedDisplay){channel.postMessage({type:'update',paused:true,verses:[],ts:Date.now()});return;}if(!canShow()){channel.postMessage({type:'update',paused:true,verses:[],ts:Date.now()});return;}channel.postMessage(outgoing());}

function openDisplay(){if(!accountStillValid())return false;if(!canShow()){notify('اختر طالبًا قبل فتح نافذة المشاركة','error');return false;}closeStudentDisplay();const session=b.sessionId||newId();b.sessionId=session;const url=new URL('imam-board-display.html',location.href);url.searchParams.set('sid',session);const w=g.open(url.toString(),'imam-board-display','width=1280,height=720');if(!w){notify('السماح بالنوافذ المنبثقة مطلوب لفتح شاشة الطالب','error');return false;}display=w;displaySecret=g.crypto?.randomUUID?.()||null;if(!displaySecret){notify('المتصفح لا يدعم إنشاء قناة مشاركة آمنة','error');closeStudentDisplay();return false;}channel?.close();channel=new BroadcastChannel(`imam-board:${currentUser()}:${session}:${displaySecret}`);channel.onmessage=e=>{if(e.data?.type==='ready')broadcast();};displayHeartbeat=setInterval(()=>{if(!accountStillValid()||!display||display.closed){closeStudentDisplay();return;}broadcast();},5000);let attempts=0;const handshake=setInterval(()=>{if(!display||display.closed||attempts++>15){clearInterval(handshake);return;}display.postMessage({type:'imam-board-init',session,channel:`imam-board:${currentUser()}:${session}:${displaySecret}`},location.origin);if(attempts>10)clearInterval(handshake);},300);return true;}
function showEffect(emoji){b.effect=emoji;const host=$('ib-effects');if(!host)return;const count=emoji==='🎈'?10:emoji==='👏'?4:8;for(let i=0;i<count;i++){const node=document.createElement('span');node.textContent=emoji;node.style.left=(7+i*(85/count))+'%';node.style.animationDelay=(i*.12)+'s';host.append(node);setTimeout(()=>node.remove(),2500);}broadcast();setTimeout(()=>{if(b.effect===emoji){b.effect='';broadcast();}},2400);}
function shutdownAudio(){if(audio){try{audio.pause();audio.src='';}catch(_){}audio=null;}try{speechSynthesis.cancel();}catch(_){}}
function speak(){if(b.muted)return;shutdownAudio();const text=$('ib-cheer')?.value||surprise[0];if(typeof SpeechSynthesisUtterance==='undefined'){notify('لا توجد أصوات عربية على هذا الجهاز. يمكن توصيل تسجيلات مرخصة لاحقًا.','info');return;}try{tts=new SpeechSynthesisUtterance(text);tts.lang='ar-EG';tts.rate=.92;tts.volume=b.volume/100;speechSynthesis.speak(tts);}catch(_){notify('تعذر تشغيل التشجيع الصوتي','error');}}
function playAyah(){if(!b.verses.length)return;shutdownAudio();const id=$('ib-reciter').value;const url=typeof g.everyAyahURL==='function'?g.everyAyahURL(id,b.chapter,b.verse):`https://everyayah.com/data/${encodeURIComponent(id)}/${String(b.chapter).padStart(3,'0')}${String(b.verse).padStart(3,'0')}.mp3`;audio=new Audio(url);audio.volume=b.volume/100;audio.play().catch(()=>notify('تعذر تشغيل التلاوة. تحقق من الإنترنت أو ملف الصوت المحمّل.','error'));}
function stopTimer(){if(timer){timerElapsed+=Math.floor((Date.now()-timerStartedAt)/1000);clearInterval(timer);timer=null;}renderClock();}
function renderClock(){const seconds=timerPreset>0?Math.max(0,timerPreset-timerElapsed):timerElapsed;const el=$('ib-clock');if(el)el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function resetTimer(){clearInterval(timer);timer=null;timerElapsed=0;timerStartedAt=0;renderClock();}
function startTimer(){if(timer){stopTimer();return;}if(timerPreset>0&&timerElapsed>=timerPreset)timerElapsed=0;timerStartedAt=Date.now();timer=setInterval(()=>{const elapsed=timerElapsed+Math.floor((Date.now()-timerStartedAt)/1000),seconds=timerPreset>0?Math.max(0,timerPreset-elapsed):elapsed;const el=$('ib-clock');if(el)el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(timerPreset>0&&elapsed>=timerPreset){stopTimer();notify('انتهى وقت النشاط. الحصة لا تُعتمد تلقائيًا.','info');}},400);}

function shape(type,points){const data={id:newId(),kind:type,points,color:$('ib-color').value,width:Number($('ib-width').value),chapter:b.chapter,from:b.from,to:b.to};b.drawings.push(data);b.redo=[];dirty();drawCanvas();broadcast();}
function coord(e){const rect=$('ib-area').getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height))};}
function pointerDown(e){if(!e.target.closest('#ib-draw'))return;if(!['pen','highlight','line','arrow','rectangle','circle','erase'].includes(paintTool))return;pointer=true;poly=[coord(e)];e.target.setPointerCapture?.(e.pointerId);}
function pointerMove(e){if(!pointer||!poly||!e.target.closest('#ib-draw'))return;poly.push(coord(e));drawCanvas(poly);}
function pointerUp(e){if(!pointer||!poly)return;pointer=false;const points=poly;poly=null;if(paintTool==='erase'){const p=points.at(-1);if(!p)return;let nearest=-1,best=.06;for(let i=0;i<b.drawings.length;i++){for(const at of b.drawings[i].points){const d=Math.hypot(at.x-p.x,at.y-p.y);if(d<best){best=d;nearest=i;}}}if(nearest>=0){b.drawings.splice(nearest,1);dirty();drawCanvas();broadcast();}return;}if(points.length)shape(paintTool,points);}
function drawCanvas(temp){const svg=$('ib-draw');if(!svg)return;svg.replaceChildren();svg.setAttribute('viewBox','0 0 1000 1000');svg.setAttribute('preserveAspectRatio','none');for(const row of [...b.drawings,...(temp?[{kind:paintTool,points:temp,color:$('ib-color').value,width:Number($('ib-width').value)}]:[])]){if(row.chapter&&(row.chapter!==b.chapter||Number(row.from)!==Number(b.from)||Number(row.to)!==Number(b.to)))continue;const points=row.points||[];if(!points.length)continue;const a=points[0],z=points[points.length-1];let node;if(['pen','highlight','line','arrow'].includes(row.kind)){node=document.createElementNS('http://www.w3.org/2000/svg','polyline');node.setAttribute('points',(row.kind==='line'||row.kind==='arrow'?[a,z]:points).map(p=>`${p.x*1000},${p.y*1000}`).join(' '));node.setAttribute('fill','none');node.setAttribute('stroke',row.color);node.setAttribute('stroke-width',Number(row.width)*2);node.setAttribute('opacity',row.kind==='highlight'?'0.3':'0.9');node.setAttribute('stroke-linecap','round');}else if(row.kind==='rectangle'){node=document.createElementNS('http://www.w3.org/2000/svg','rect');node.setAttribute('x',Math.min(a.x,z.x)*1000);node.setAttribute('y',Math.min(a.y,z.y)*1000);node.setAttribute('width',Math.abs(a.x-z.x)*1000);node.setAttribute('height',Math.abs(a.y-z.y)*1000);node.setAttribute('fill','none');node.setAttribute('stroke',row.color);node.setAttribute('stroke-width',row.width*2);}else{node=document.createElementNS('http://www.w3.org/2000/svg','ellipse');node.setAttribute('cx',(a.x+z.x)*500);node.setAttribute('cy',(a.y+z.y)*500);node.setAttribute('rx',Math.abs(a.x-z.x)*500);node.setAttribute('ry',Math.abs(a.y-z.y)*500);node.setAttribute('fill','none');node.setAttribute('stroke',row.color);node.setAttribute('stroke-width',row.width*2);}svg.append(node);}}
function normalizeStage(s){const c=cleanNumber(s.chapter,1,114,b.chapter),f=cleanNumber(s.from,1,286,1),t=cleanNumber(s.to,f,286,f);return{id:cleanText(s.id||newId(),100),type:SAFE_STAGE_TYPES.includes(s.type)?s.type:'شرح',title:cleanText(s.title,120),chapter:c,from:f,to:t,minutes:cleanNumber(s.minutes,0,120,3),prompt:cleanText(s.prompt,650),publicExplanation:cleanText(s.publicExplanation,1200),scienceBook:root.BoardCorpus?.BOOKS?.includes(s.scienceBook)?s.scienceBook:'التفسير الميسر',hide:!!s.hide};}
function prepareDraft(source){const stages=Array.isArray(source?.lesson)?source.lesson.map(x=>typeof x==='string'?normalizeStage({type:'شرح',title:x,chapter:source.chapter,from:source.from,to:source.to}):normalizeStage(x)).slice(0,40):[];return {id:source?.id||newId(),title:cleanText(source?.title||'تحضير الحصة القرآنية',120),studentId:source?.studentId??b.studentId,group:cleanText(source?.group||'',100),date:cleanText(source?.date||new Date().toISOString().slice(0,10),10),objective:cleanText(source?.objective||'',700),chapter:source?.chapter||b.chapter,from:source?.from||b.from,to:source?.to||b.to,lesson:stages.length?stages:[stageTemplate('ترحيب'),stageTemplate('مراجعة'),stageTemplate('حفظ جديد'),stageTemplate('تسميع'),stageTemplate('ختام')],publicExplanation:cleanText(source?.publicExplanation||'',1200),createdAt:source?.createdAt||Date.now(),updatedAt:Date.now(),status:source?.status||'draft'};}
function modalClose(){const el=$('ib-prep-modal');if(el)el.remove();prepEditing=null;}
function openPreparation(source){if(!accountStillValid())return;modalClose();prepEditing=prepareDraft(source);const overlay=document.createElement('div');overlay.id='ib-prep-modal';overlay.className='ib-prep-overlay';overlay.dir='rtl';overlay.innerHTML=`<section class="ib-prep-dialog" role="dialog" aria-modal="true" aria-label="التحضير قبل الحصة"><header><h2>🗂️ التحضير قبل الحصة</h2><p>التحضير تعليمي؛ لا يغيّر تكليفًا معتمدًا أو ينشئ حصة رسمية.</p><button type="button" data-prep="close">إغلاق</button></header><div class="ib-prep-fields"><label>عنوان التحضير<input data-prep-field="title" maxlength="120"></label><label>تاريخ الحصة<input type="date" data-prep-field="date"></label><label>الطالب<select data-prep-field="studentId"><option value="">تحضير عام</option>${optionList()}</select></label><label>هدف الحصة<textarea data-prep-field="objective" maxlength="700"></textarea></label><label>مجموعة التحضير<input data-prep-field="group" maxlength="100"></label></div><div class="ib-prep-heading"><h3>تسلسل الأنشطة</h3><button type="button" data-prep="add">إضافة نشاط</button></div><div id="ib-prep-stages"></div><footer><button data-prep="save">حفظ التحضير</button><button data-prep="ready">حفظه كجاهز</button><button data-prep="use">بدء السبورة من التحضير</button><button data-prep="preview">معاينة تعليمية</button></footer><div class="ib-small" role="status" id="ib-prep-result"></div></section>`;
 document.querySelector('#imam-board-root').append(overlay);
 for(const key of ['title','date','objective','group','studentId'])overlay.querySelector(`[data-prep-field="${key}"]`).value=prepEditing[key]||'';
 overlay.addEventListener('input',e=>{const key=e.target.dataset.prepField;if(key&&prepEditing)prepEditing[key]=cleanText(e.target.value,key==='objective'?700:120);if(key==='studentId'&&prepEditing)prepEditing.studentId=e.target.value;const n=Number(e.target.dataset.step);const field=e.target.dataset.field;if(prepEditing&&field&&Number.isInteger(n)&&prepEditing.lesson[n]){const stage=prepEditing.lesson[n];stage[field]=field==='minutes'||field==='chapter'||field==='from'||field==='to'?Number(e.target.value):cleanText(e.target.value,field==='publicExplanation'?1200:650);}});
 overlay.addEventListener('change',e=>{if(e.target.dataset.field==='hide'&&prepEditing){const st=prepEditing.lesson[Number(e.target.dataset.step)];if(st)st.hide=e.target.checked;}});
 overlay.addEventListener('click',e=>{const el=e.target.closest('button[data-prep]');if(!el)return;e.stopPropagation();const cmd=el.dataset.prep,n=Number(el.dataset.step);if(cmd==='close'){modalClose();return;}if(!prepEditing)return;if(cmd==='add'){if(prepEditing.lesson.length>=40)return notify('الحد الأقصى 40 خطوة','error');prepEditing.lesson.push(stageTemplate());renderPrepStages();return;}if(['up','down','delete'].includes(cmd)&&prepEditing.lesson[n]){if(cmd==='delete')prepEditing.lesson.splice(n,1);else{const i=cmd==='up'?n-1:n+1;if(i>=0&&i<prepEditing.lesson.length)[prepEditing.lesson[n],prepEditing.lesson[i]]=[prepEditing.lesson[i],prepEditing.lesson[n]];}renderPrepStages();return;}if(['save','ready','use','preview'].includes(cmd)){if(!persistPreparation(cmd==='ready'||cmd==='use'?'ready':'draft'))return;if(cmd==='use'||cmd==='preview'){usePreparation(prepEditing,{preview:cmd==='preview'});modalClose();}else $('ib-prep-result').textContent='تم الحفظ مع عدم تغيير التكليف الرسمي.';}});
 renderPrepStages();}
function renderPrepStages(){const target=$('ib-prep-stages');if(!target||!prepEditing)return;target.innerHTML=prepEditing.lesson.map((x,i)=>`<article class="ib-prep-stage"><div class="ib-prep-stage-title"><strong>الخطوة ${i+1}</strong><button data-prep="up" data-step="${i}" aria-label="تحريك للأعلى">↑</button><button data-prep="down" data-step="${i}" aria-label="تحريك للأسفل">↓</button><button data-prep="delete" data-step="${i}" aria-label="حذف النشاط">حذف</button></div><div class="ib-prep-stage-fields"><label>النشاط<select data-step="${i}" data-field="type">${SAFE_STAGE_TYPES.map(type=>`<option ${x.type===type?'selected':''}>${esc(type)}</option>`).join('')}</select></label><label>الاسم<input data-step="${i}" data-field="title" value="${esc(x.title)}" maxlength="120"></label><label>سورة<input data-step="${i}" data-field="chapter" type="number" min="1" max="114" value="${x.chapter}"></label><label>من آية<input data-step="${i}" data-field="from" type="number" min="1" value="${x.from}"></label><label>إلى آية<input data-step="${i}" data-field="to" type="number" min="1" value="${x.to}"></label><label>المدة بالدقائق<input data-step="${i}" data-field="minutes" type="number" min="0" max="120" value="${x.minutes}"></label><label>مصدر التفسير المطلوب للتحضير<select data-step="${i}" data-field="scienceBook">${(root.BoardCorpus?.BOOKS||['التفسير الميسر']).map(book=>`<option ${x.scienceBook===book?'selected':''}>${esc(book)}</option>`).join('')}</select></label><label class="ib-prep-wide">السؤال أو التعليمة<input data-step="${i}" data-field="prompt" value="${esc(x.prompt)}" maxlength="650"></label><label class="ib-prep-wide">شرح يظهر للطالب عند اختيار المحفظ<input data-step="${i}" data-field="publicExplanation" value="${esc(x.publicExplanation)}" maxlength="1200"></label><label>إخفاء الكلمات عند بدء النشاط <input type="checkbox" data-step="${i}" data-field="hide" ${x.hide?'checked':''}></label></div></article>`).join('');}
function persistPreparation(statusValue='draft'){if(!prepEditing)return false;const prep={...prepEditing,lesson:prepEditing.lesson.map(normalizeStage),status:statusValue,updatedAt:Date.now()};if(!prep.title.trim())return notify('اكتب عنوانًا للتحضير','error'),false;for(const st of prep.lesson){if(!validRange(st.chapter,st.from,st.to)){notify('تحقق من أرقام السور والآيات في خطوات التحضير','error');return false;}}try{const base=readStore(),preps=Array.isArray(base.preps)?base.preps:[];const ix=preps.findIndex(x=>x.id===prep.id);if(ix<0)preps.push(prep);else preps[ix]=prep;writeStore({...base,preps:preps.slice(-100)});prepEditing=prep;return true;}catch(e){notify('تعذر حفظ التحضير: '+e.message,'error');return false;}}
function usePreparation(source,{preview=false}={}){if(b.dirty&&!flush())return false;if(source.studentId&&String(source.studentId)!==String(b.studentId)){if(!students().some(s=>String(s.id)===String(source.studentId)))return notify('الطالب المحدد لم يعد متاحًا في هذا الحساب','error'),false;chooseStudent(String(source.studentId));}const prep=prepareDraft(source);b.lesson=prep.lesson.map(normalizeStage);b.stepIndex=0;b.activePrepId=preview?'':prep.id;b.publicExplanation='';b.preview=!!preview;const pub=$('ib-public');if(pub)pub.value='';if(b.lesson.length)loadTimelineStep(0);dirty();updateTimeline();return true;}
function loadPreparation(){const all=(readStore().preps||[]).filter(p=>p&&p.id);if(!all.length)return notify('لا توجد تحضيرات محفوظة','info');const n=Number(prompt('اختر التحضير:\n'+all.slice(-20).map((p,i)=>`${i+1}. ${p.title} (${p.status==='ready'?'جاهز':'مسودة'})`).join('\n')));const src=all.slice(-20)[n-1];if(src)openPreparation(src);}
function copyPreparationToStudent(){const all=(readStore().preps||[]).filter(p=>p&&p.id);if(!all.length)return notify('لا توجد قوالب','info');const n=Number(prompt(all.slice(-20).map((p,i)=>`${i+1}. ${p.title}`).join('\n')));const src=all.slice(-20)[n-1];if(!src)return;const copy=prepareDraft({...src,id:newId(),studentId:b.studentId,group:'',date:new Date().toISOString().slice(0,10),status:'draft',createdAt:Date.now()});copy.lesson=copy.lesson.map(x=>({...x,id:newId()}));openPreparation(copy);notify('نسخة تعليمية جديدة لا تنقل درجات أو أخطاء الطالب السابق','info');}
function updateTimeline(){const holder=$('ib-timeline');if(!holder)return;if(!b.lesson.length){holder.textContent='لا توجد خطوات تحضير نشطة';return;}holder.replaceChildren();const header=document.createElement('div');header.textContent=`تسلسل الدرس — ${b.stepIndex+1} من ${b.lesson.length}`;holder.append(header);b.lesson.forEach((x,i)=>{const btn=document.createElement('button');btn.type='button';btn.dataset.timeline=i;btn.textContent=`${i+1} · ${x.title||x.type}`;btn.classList.toggle('on',i===b.stepIndex);holder.append(btn);});}
function loadTimelineStep(index){if(index<0||index>=b.lesson.length)return;const x=normalizeStage(b.lesson[index]);if(!validRange(x.chapter,x.from,x.to))return notify('نطاق هذا النشاط غير صحيح','error');b.stepIndex=index;b.scienceBook=x.scienceBook;if($('ib-book-select'))$('ib-book-select').value=b.scienceBook;b.chapter=x.chapter;b.from=x.from;b.to=x.to;const ch=$('ib-chapter'),from=$('ib-from'),to=$('ib-to');if(ch)ch.value=b.chapter;if(from)from.value=b.from;if(to)to.value=b.to;b.publicExplanation=x.publicExplanation||'';if($('ib-public'))$('ib-public').value=b.publicExplanation;b.game=x.prompt||'';if(x.hide)b.curtain=Array.from({length:x.to-x.from+1},(_,i)=>x.from+i);loadVerses().then(()=>{renderScience();if(x.hide){b.curtain=Array.from({length:x.to-x.from+1},(_,i)=>x.from+i);showVerses();}});dirty();updateTimeline();}

function exportBoard(){
 if(!b.verses.length)return notify('افتح آيات السبورة أولًا','info');
 // Export only explicitly public teaching content, no personal guardian/teacher data.
 const title=`أكاديمية الإمام — ملخص السبورة التعليمية`;
 const paragraphs=b.verses.map(v=>`<p><b>﴿${esc(v.ayah)}﴾</b> ${esc(v.text)}</p>`).join('');
 const html=`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>${title}</title><style>body{font:19px/2 system-ui;background:#fffdf3;color:#143b29;margin:35px}h1{text-align:center;color:#176045;border-bottom:3px solid #c49e58;padding:18px}article{font:26px/2.4 'Traditional Arabic',serif}p{margin:8px 0}aside{background:#e9f5ee;padding:15px;border-radius:12px}@page{size:A4;margin:15mm}</style><h1>${title}</h1><h2>سورة ${esc((typeof S!=='undefined'?S:[])[b.chapter-1]?.n||'')} — الآيات ${b.from} إلى ${b.to}</h2><article>${paragraphs}</article><aside>${esc(b.publicExplanation)}</aside><p>وثيقة شرح تعليمية؛ لا تثبت اعتماد التسميع أو منح شهادة.</p></html>`;
 const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`imam-board-${b.chapter}-${b.from}-${b.to}.html`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);
}
function pickRandomStudent(){const list=visibleStudents().filter(s=>!absentToday(s.id)&&!completedToday(s.id));if(!list.length)return notify('لا يوجد طلاب مؤهلون للاختيار','info');const choice=list[Math.floor(Math.random()*list.length)];chooseStudent(String(choice.id));notify('الطالب المختار: '+(choice.name||choice.fullName||'طالب'),'success');}
function showTajweedCard(){if(!b.verses.length)return notify('اختر موضعًا قرآنيًا','info');const rule=prompt('ما الحكم التجويدي الذي تريد شرحه؟ (يحدده المحفظ يدويًا)');if(!rule)return;const explanation=prompt('شرح الحكم وموضعه؛ لا تعتمد على تفسير آلي',b.teacherWord||'')||'';b.publicExplanation=`الحكم: ${rule.slice(0,100)}. ${explanation.slice(0,500)}`;const box=$('ib-public');if(box)box.value=b.publicExplanation;dirty();broadcast();}
function toggleExpanded(){document.querySelector('.ib-shell')?.classList.toggle('ib-expanded');}
function loadDraft(){const all=(readStore().sessions||[]).filter(s=>!b.studentId||s.studentId===b.studentId);if(!all.length)return notify('لا توجد مسودات محفوظة لهذا الحساب','info');const n=Number(prompt(all.slice(-12).map((p,i)=>`${i+1} ـ ${new Date(p.updatedAt).toLocaleString('ar-EG')} · ${p.activity}`).join('\n')));const p=all.slice(-12)[n-1];if(!p)return;if(p.studentId&&!students().some(s=>String(s.id)===String(p.studentId)))return notify('هذا الطالب لم يعد متاحًا لهذا الحساب','error');if(b.dirty&&!flush())return;closeStudentDisplay();quranRequest++;Object.assign(b,{studentId:p.studentId,sessionId:p.id,chapter:p.chapter,from:p.from,to:p.to,activity:p.activity,drawings:p.drawings||[],notes:p.notes||[],lesson:p.lesson||[],stepIndex:p.stepIndex||0,activePrepId:p.activePrepId||'',privateNote:p.privateNote||'',publicExplanation:p.publicExplanation||'',scienceBook:root.BoardCorpus?.BOOKS?.includes(p.scienceBook)?p.scienceBook:'التفسير الميسر',teacherWord:'',dirty:false,savedAt:p.updatedAt});$('ib-chapter').value=b.chapter;$('ib-from').value=b.from;$('ib-to').value=b.to;$('ib-private').value=b.privateNote;$('ib-public').value=b.publicExplanation;updateStudents();updateActivity();updateAssignments();if($('ib-book-select'))$('ib-book-select').value=b.scienceBook;renderScience();loadVerses().then(()=>{b.dirty=false;updateSummary();updateTimeline();});}
function closeNativeEditor(){
 if(!nativeEditor)return;
 const page=nativeEditor;
 const placeholder=nativePlaceholder;
 // Restore the very same DOM nodes. Do not recreate the editor or change unsaved grades/errors.
 if(placeholder?.parentNode)placeholder.replaceWith(page);
 nativeEditor=null;nativePlaceholder=null;nativeEditorStudent='';
 $('ib-native-overlay')?.setAttribute('hidden','');
 document.body.classList.remove('ib-native-open');
}
function openNativeEditor(){
 if(b.preview)return notify('أنهِ المعاينة قبل تسجيل تقييم رسمي','error');
 if(!canShow()||!accountStillValid())return notify('اختر طالبًا مصرحًا به أولًا','error');
 if(nativeEditor)return;
 if(b.dirty&&!flush())return;
 const page=$('pg-session'),mount=$('ib-native-mount');
 if(!page||!mount||typeof g.onSesSt!=='function')return notify('محرر الحصة الأصلي غير متاح؛ لن ننشئ بديلًا غير موثق','error');
 // Do not navigate the app: goPage('session') calls initSession() and may reset an
 // existing unfinished edit. Initialize the existing editor only if never initialized.
 if(($('sesSt')?.options?.length||0)<2&&typeof g.initSession==='function')g.initSession();
 const previousStudent=String($('sesSt')?.value||'');
 if(previousStudent&&previousStudent!==String(b.studentId) &&
    !confirm('سيتم الانتقال إلى حصة طالب آخر. احفظ أي تعديل غير محفوظ في محرر الحصة السابق قبل الاستمرار. متابعة؟'))return;
 // Only the legacy editor handles the real records. Board carries no independent grading state.
 try{
   const select=$('sesSt');
   if(!select||!Array.from(select.options).some(x=>String(x.value)===String(b.studentId)))throw Error('الطالب غير موجود داخل محرر الحصة المصرح به');
   if(String(select.value)!==String(b.studentId)){select.value=String(b.studentId);g.onSesSt();}
   nativePlaceholder=document.createComment('imam-board-original-session-position');
   page.parentNode.insertBefore(nativePlaceholder,page);
   mount.appendChild(page);nativeEditor=page;nativeEditorStudent=String(b.studentId);
   $('ib-native-overlay').removeAttribute('hidden');document.body.classList.add('ib-native-open');
   $('ib-native-status').textContent='التصحيح والتقديرات هنا مرتبطة بسجل الطالب الحالي؛ احفظ الحصة عندما تكتمل';
 }catch(error){
   // Fail closed: do not leave the legacy editor orphaned or create any session.
   if(nativeEditor)closeNativeEditor();
   else{if(nativePlaceholder?.parentNode)nativePlaceholder.replaceWith(page);nativePlaceholder=null;document.body.classList.remove('ib-native-open');}
   notify(error?.message||'تعذر فتح محرر الحصة','error');
 }
}
function openNativeQuran(){
 if(!nativeEditor||nativeEditorStudent!==String(b.studentId)||!accountStillValid())return;
 const surah=(typeof S!=='undefined'?S:[])[b.chapter-1]?.n;
 if(!surah||!validRange(b.chapter,b.from,b.to)||typeof g.openQuranRangeText!=='function')return notify('نطاق التصحيح القرآني غير متاح','error');
 // The Quran modal and its word/character annotations are the existing, official implementation.
 g.openQuranRangeText({surah,from:b.from,to:b.to});
}
function saveNativeSession(){
 if(!nativeEditor||nativeEditorStudent!==String(b.studentId)||!accountStillValid())return notify('محرر الحصة غير مرتبط بالطالب الحالي','error');
 if(String($('sesSt')?.value||'')!==nativeEditorStudent)return notify('الطالب داخل محرر الحصة مختلف؛ لم يتم الحفظ','error');
 if(typeof g.saveSession!=='function')return notify('حفظ الحصة المعتمد غير متاح','error');
 // The original save function validates, persists and triggers downstream revision/report hooks.
 try{const row=g.saveSession();if(row&&String(row.studentId)===nativeEditorStudent){$('ib-native-status').textContent='تم حفظ الحصة رسميًا بواسطة محرك الأكاديمية';notify('تم حفظ الحصة بنظام الأكاديمية المعتمد','success');updateStudents();}else{$('ib-native-status').textContent='لم يثبت حفظ الحصة؛ راجع حقول التسميع';}}
 catch(_){$('ib-native-status').textContent='تعذر الحفظ؛ راجع السجل قبل مغادرة المحرر';notify('تعذر حفظ الحصة، لم يتم اعتماد نتيجة من السبورة','error');}
}
function openLegacy(){openNativeEditor();}
function correction(){openNativeEditor();}
function finish(){if(b.preview)return notify('المعاينة لا تنشئ نتائج رسمية','info');if(!canShow())return notify('اختر الطالب أولًا','error');if(b.dirty&&!flush())return;openNativeEditor();notify('راجع الأنشطة الناقصة والتقديرات ثم احفظ من محرر الحصة الرسمي','info');}

function click(e){const t=e.target.closest?.('button');if(!t)return;if(t.dataset.timeline!==undefined){loadTimelineStep(Number(t.dataset.timeline));return;}if(t.dataset.activity)return chooseActivity(t.dataset.activity);if(t.dataset.tool){paintTool=t.dataset.tool;$('ib-area')?.classList.toggle('ib-paint',!['choose','curtain','hide','focus','lens'].includes(paintTool));document.querySelectorAll('[data-tool]').forEach(x=>x.classList.toggle('on',x.dataset.tool===paintTool));if(paintTool==='focus'||paintTool==='lens'){$('ib-area').classList.toggle('ib-focus',paintTool==='focus');$('ib-area').classList.toggle('ib-lens',paintTool==='lens');}return;}if(t.dataset.emotion)return showEffect(t.dataset.emotion);if(t.dataset.selectAyah){b.verse=Number(t.dataset.selectAyah);b.teacherWord='';renderScience();broadcast();return;}if(t.classList.contains('ib-word')){b.verse=Number(t.dataset.ayah);const k=`${t.dataset.ayah}:${t.dataset.word}`;if(paintTool==='hide'){b.hides=b.hides.includes(k)?b.hides.filter(x=>x!==k):[...b.hides,k];showVerses();}else if(paintTool==='curtain'){const n=Number(t.dataset.ayah);b.curtain=b.curtain.includes(n)?b.curtain.filter(x=>x!==n):[...b.curtain,n];showVerses();}else{b.teacherWord=t.dataset.value;renderScience();}broadcast();return;}const cmd=t.dataset.cmd;if(!cmd)return;switch(cmd){case 'close':exit();break;case 'native-close':closeNativeEditor();break;case 'native-quran':openNativeQuran();break;case 'native-save':saveNativeSession();break;case 'save':flush();break;case 'reading':reading();break;case 'showAll':b.hides=[];b.curtain=[];showVerses();break;case 'completeGame':{if(!b.verses.length)break;const v=b.verses.find(x=>x.ayah===b.verse)||b.verses[0];const words=String(v.text).trim().split(/\s+/).filter(Boolean);if(words.length){b.hides.push(`${v.ayah}:${words.length-1}`);b.game='أكمل الكلمة المخفية من الآية الكريمة';showVerses();}break;}case 'pauseDisplay':pauseDisplay();break;case 'display':openDisplay();break;case 'share':openDisplay();notify('شارك نافذة الطالب فقط من زوم أو تيمز أو ميت. فعّل مشاركة صوت الجهاز يدويًا.','info');break;case 'loadVerses':loadVerses();break;case 'previous':case 'nextStudent':{const arr=visibleStudents();const index=arr.findIndex(x=>String(x.id)===b.studentId);chooseStudent(String(arr[Math.min(arr.length-1,Math.max(0,index+(cmd==='previous'?-1:1)))]?.id||''));break;}case 'new':if(b.dirty&&!flush())return;closeStudentDisplay();b.sessionId=newId();b.drawings=[];b.notes=[];b.lesson=[];b.stepIndex=0;b.activePrepId='';b.preview=false;drawCanvas();updateTimeline();dirty();break;case 'loadDraft':loadDraft();break;case 'loadPrep':loadPreparation();break;case 'copyPrep':copyPreparationToStudent();break;case 'wheel':pickRandomStudent();break;case 'export':exportBoard();break;case 'expand':toggleExpanded();break;case 'scienceImport':scientificImporter();break;case 'scienceMultiImport':multiScienceImporter();break;case 'scienceShareImported':shareImportedScience();break;case 'scienceShareMulti':shareMultiScience();break;case 'scienceEdit':scienceEditor();break;case 'scienceCancel':$('ib-science-editor')?.remove();break;case 'scienceShare':shareScienceCard();break;case 'scienceQuiz':scienceQuiz();break;case 'tajweed':showTajweedCard();break;case 'prepare':openPreparation();break;case 'nextPart':loadReviewPart(Math.min(b.rangeParts.length-1,(b.partIndex||0)+1));break;case 'previousPart':loadReviewPart(Math.max(0,(b.partIndex||0)-1));break;case 'timelinePrev':loadTimelineStep(Math.max(0,b.stepIndex-1));break;case 'timelineNext':loadTimelineStep(Math.min(b.lesson.length-1,b.stepIndex+1));break;case 'lesson':if(b.lesson.length)notify('اختر خطوة من تسلسل الدرس بجوار الطالب','info');else openPreparation();break;case 'bigger':b.fontSize=Math.min(64,b.fontSize+3);showVerses();break;case 'smaller':b.fontSize=Math.max(18,b.fontSize-3);showVerses();break;case 'prevAyah':b.verse=Math.max(b.from,b.verse-1);b.teacherWord='';renderScience();broadcast();break;case 'nextAyah':b.verse=Math.min(b.to,b.verse+1);b.teacherWord='';renderScience();broadcast();break;case 'undo':{const row=b.drawings.pop();if(row){b.redo.push(row);dirty();drawCanvas();broadcast();}break;}case 'redo':{const row=b.redo.pop();if(row){b.drawings.push(row);dirty();drawCanvas();broadcast();}break;}case 'clear':if(confirm('مسح الرسومات فقط؟ لن تُمس الآيات أو أخطاء التسميع.')){b.drawings=[];dirty();drawCanvas();broadcast();}break;case 'audio':playAyah();break;case 'stopAudio':shutdownAudio();break;case 'timer':startTimer();break;case 'timerReset':resetTimer();break;case 'question':b.game=prompt('اكتب سؤالًا تعليميًا مناسبًا للمشاركة')||'';dirty();broadcast();break;case 'preview':if(b.preview){b.preview=false;closeStudentDisplay();status('انتهت المعاينة؛ يمكن متابعة الحصة');}else{b.preview=openDisplay()===true;}break;case 'cheer':speak();break;case 'mute':b.muted=!b.muted;shutdownAudio();status(b.muted?'الأصوات مكتومة':'تم تفعيل الصوت');break;case 'explain':b.publicExplanation=$('ib-public').value;dirty();broadcast();break;case 'quranCorrection':correction();break;case 'session':openLegacy();break;case 'finish':finish();break;}}
function change(e){if(e.target.id==='ib-book-select'){if(root.BoardCorpus?.BOOKS?.includes(e.target.value)&&e.target.value!==b.scienceBook){b.scienceBook=e.target.value;dirty();}renderScience();return;}if(e.target.id==='ib-timer-preset'){resetTimer();timerPreset=cleanNumber(e.target.value,0,600,0);renderClock();return;}if(e.target.id==='ib-volume'){b.volume=cleanNumber(e.target.value,0,100,85);if(audio)audio.volume=b.volume/100;return;}if(e.target.id==='ib-group'){const next=e.target.value;if(next!==b.groupFilter){if(b.dirty&&!flush()){e.target.value=b.groupFilter;return;}b.groupFilter=next;if(b.studentId&&!visibleStudents().some(s=>String(s.id)===String(b.studentId)))chooseStudent('');updateStudents();}}if(e.target.id==='ib-student')chooseStudent(e.target.value);if(e.target.id==='ib-chapter'){b.chapter=Number(e.target.value)||1;dirty();}if(['ib-from','ib-to'].includes(e.target.id)){b[e.target.id==='ib-from'?'from':'to']=Number(e.target.value);dirty();}}
function input(e){if(e.target.id==='ib-private'){b.privateNote=e.target.value;dirty();}if(e.target.id==='ib-public'){b.publicExplanation=e.target.value;dirty();}}
function keyboard(e){if(e.target.matches('input,textarea,select,[contenteditable]'))return;if(e.key==='Escape'){reading();return;}if(e.key==='ArrowLeft'){b.verse=Math.max(b.from,b.verse-1);b.teacherWord='';renderScience();broadcast();}if(e.key==='ArrowRight'){b.verse=Math.min(b.to,b.verse+1);b.teacherWord='';renderScience();broadcast();}}
g.addEventListener?.('pagehide',()=>{if(active&&b.dirty&&sessionUser===currentUser())flush();closeStudentDisplay();shutdownAudio();});
document.addEventListener?.('visibilitychange',()=>{if(active&&document.visibilityState==='hidden'&&b.dirty&&sessionUser===currentUser())flush();});
function open(){try{assertUser();}catch(err){return notify(err.message,'error');}if(active){$('imam-board-root')?.scrollIntoView();return;}active=true;sessionUser=currentUser();b.sessionId=newId();b.groupFilter='';renderShell();clearInterval(accountWatch);accountWatch=setInterval(dropPrivateBoardOnAccountChange,1000);}
root.SmartBoard=Object.freeze({open,close:exit,save:flush,returnToReading:reading,getSnapshot:()=>({studentId:b.studentId,chapter:b.chapter,from:b.from,to:b.to,activity:b.activity,dirty:b.dirty}),getVersion:()=> '11.12.1-beta.6'});
